const state={selected:read('selected','A-21'),floor:3,photo:'exterior',zoom:1.02,favorites:read('favorites',[]),compare:read('compare',[]),filters:{query:'',beds:'all',block:'all',status:'all',sort:'featured'},page:1,unitTab:'overview',galleryIndex:0,dialogGallery:[],accounts:read('accounts',[]),accountEdits:read('accountEdits',{}),deals:read('deals',null),visits:read('visits',[]),messages:read('messages',{}),profile:read('profile',{name:'Alex Morgan',email:'alex.morgan@example.com',phone:'+1 202 555 0110',role:'Workspace owner'}),theme:read('theme','light'),motion:read('motion',true),sceneVisible:true,calendarMonth:9,calendarYear:2026,calendarDay:'2026-10-15',conversation:'account-5'};
const money=(v,short=false)=>short&&v>=1000000?'$'+(v/1000000).toFixed(1)+'M':'$'+Math.round(v).toLocaleString('en-US');const num=(v,d=0)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d});const unit=id=>D.units.find(u=>u.id===id)||D.units[20];let currentPage='overview';
const advisors=D.advisors;const allAccounts=()=>[...D.accounts,...state.accounts].map(a=>({...a,...state.accountEdits[a.id],...(a.id==='account-1'?state.profile:{})}));const person=id=>allAccounts().find(a=>a.id===id)||advisors.find(a=>a.id===id)||allAccounts()[0];
