function renderNav(){const active=currentPage==='unit'?'residences':currentPage==='account'?'accounts':currentPage;$('#navRail').innerHTML=nav.map(([r,i,l],n)=>`${[3,8,11].includes(n)?'<span class="nav-gap"></span>':''}<a class="nav-item ${active===r?'active':''}" href="#${r}" aria-label="${l}" data-tip="${l}" ${active===r?'aria-current="page"':''}>${icon(i)}</a>`).join('');$('#mobileNav').innerHTML=nav.filter(n=>['overview','explore','residences','favorites','messages'].includes(n[0])).map(([r,i,l])=>`<a href="#${r}" class="${active===r?'active':''}">${icon(i)}<span>${r==='residences'?'Homes':r==='explore'?'Explore':r==='favorites'?'Saved':l}</span></a>`).join('');$('.my-avatar').textContent=state.profile.name.split(' ').map(x=>x[0]).join('').slice(0,2);document.body.classList.toggle('dark',state.theme==='dark');document.body.classList.toggle('reduce-motion',!state.motion)}
function renderScene(){const selected=unit(state.selected),ids=[D.units.find(u=>u.floor===state.floor&&u.block==='A'&&u.index===1),selected,D.units.find(u=>u.floor===state.floor&&u.block==='B'&&u.index===7)];$('#propertyScene').innerHTML=`<div class="scene-bg" style="background-image:url('assets/ghadir/${state.photo}.webp');--scene-scale:${state.zoom}"></div><div class="scene-top"><button class="scene-search" data-action="search">${icon('search')} Find a residence…</button>${button('scene-options','settings','Scene options')}${button('scene-gallery','image','Choose project image')}${goButton('explore','Explore all units','arrow','white')}</div><span class="scene-view-badge">Project design render</span><button class="scene-click" data-action="explore" aria-label="Open interactive unit selection"></button><div class="scene-heading"><span class="eyebrow">PARDISAN, QOM · GHADIR</span><h2>A new perspective<br>on coming home.</h2></div>${ids.map((u,i)=>`<button class="scene-pin pin-${i} ${i===1?'selected':''}" data-action="scene-unit" data-id="${u.id}" aria-label="Select residence ${u.id}"><span>${icon('building')}</span><span><small>BLOCK ${u.block} · FLOOR ${u.floor} · ${u.area} M²</small>${i===1?'Residence '+u.id:money(u.price)}</span></button>`).join('')}<div class="scene-footer"><div><small>The Ghadir collection</small><h3>126 homes.<br>One extraordinary place.</h3><button class="text-button" data-action="explore">Explore the residences ↗</button></div><div class="scene-tools">${button('scene-gallery','image','Change view')}${button('zoom-in','plus','Zoom in')}${button('zoom-out','minus','Zoom out')}</div></div>`}
function pageTop(eye,title,sub='',action=''){return `<div class="page-top"><div><span class="eyebrow greeting"><i></i>${eye}</span><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${action?`<div class="page-actions">${action}</div>`:''}</div>`}
function section(title,ico,link='',label='View all'){return `<div class="section-heading"><h2>${icon(ico)}${title}</h2>${link?`<a class="text-button" href="#${link}">${label}${icon('arrow')}</a>`:''}</div>`}
function photo(src,title,index,extra=''){return `<button class="photo-button" data-action="gallery" data-index="${index}" aria-label="View ${esc(title)}"><img src="${src}" alt="${esc(title)}" ${index>0?'loading="lazy"':''}><span class="expand">${icon('area')}</span>${extra}</button>`}
function features(u){return `<div class="features"><span class="feature">${icon('bed')}${u.beds} bedrooms</span><span class="feature">${icon('area')}${u.area} m²</span><span class="feature">${icon('floor')}Floor ${u.floor}</span><span class="feature">${icon('building')}Block ${u.block}</span><span class="feature">${icon('shield')}ID: ${u.id}</span></div>`}
