function renderOverview(){const u=unit(state.selected),a=person(u.advisorId);$('#main').innerHTML=`${pageTop('Your property workspace','A better view of home.','Beautiful spaces. Meaningful connections.',`<button class="pill" data-action="collection-filter">Curated for you ${icon('down')}</button>`)}<section class="featured reveal"><div class="featured-gallery">${[0,1,4].map((ix,i)=>photo(D.gallery[ix].src,D.gallery[ix].title,ix,i===0?`<span class="photo-label">${badge(u.status)}</span>`:i===2?'<span class="photo-label dark">+5 photos</span>':'')).join('')}</div><div class="featured-info"><div class="featured-line"><div><h2>Residence ${u.id} · Ghadir Collection</h2><p>Pardisan, Qom · Designed around your everyday</p></div><div class="price">${count(u.price,'$')}<small>ILLUSTRATIVE ASKING PRICE</small></div></div>${features(u)}<div class="featured-bottom"><div class="button-group"><button class="primary" data-action="book" data-id="${u.id}">Arrange a viewing</button>${goButton('unit/'+u.id,'Open residence '+u.id)}${button('favorite','heart','Save residence','',`data-id="${u.id}" aria-pressed="${state.favorites.includes(u.id)}"`)}${button('share','link','Copy residence link','',`data-id="${u.id}"`)}</div>${personInline(a)}<div class="button-group">${button('contact','phone','Contact advisor','',`data-id="${a.id}"`)}${button('message-person','mail','Message advisor','',`data-id="${a.id}"`)}</div></div></div></section>${section('Your property team','users','accounts','Meet everyone')}<div class="developer-grid">${advisors.map((a,i)=>`<article class="developer-card reveal ${i===0?'dark-card':''}" style="--delay:${i*80}ms"><div class="developer-top">${avatar(a)}<div><h3>${esc(a.name)}</h3><small>${esc(a.specialty)}</small></div>${goButton('account/'+a.id,'View '+a.name,'arrow',i===0?'white':'black')}</div><a class="property-ref" href="#unit/${['A-21','B-27','A-48'][i]}">${icon('building')}<span><small>Ghadir Residences</small>Block ${i===1?'B':'A'} · ${['Signature collection','Family collection','Upper floor collection'][i]}</span></a><div class="developer-bottom"><button class="status-control" data-action="advisor-status" data-id="${a.id}"><i></i><span>${['Available for viewings','Private consultations','Investment planning'][i]}</span>${icon('down')}</button>${button('contact','phone','Contact '+a.name,'',`data-id="${a.id}"`)}${button('message-person','mail','Message '+a.name,'',`data-id="${a.id}"`)}</div></article>`).join('')}</div><div class="bottom-grid"><section>${section('Open opportunities','deal','pipeline')}${getDeals().slice(0,2).map(deal=>`<a class="list-card reveal" href="#pipeline"><span class="list-icon">${icon('building')}</span><div class="list-main"><h3>${money(unit(deal.unitId).price)}</h3><p>Residence ${deal.unitId} · ${esc(deal.name)}</p></div><span class="icon-button black">${icon('arrow')}</span></a>`).join('')}</section><section>${section('Conversations','chat','messages')}${['account-5','account-6'].map((id,i)=>{let a=person(id);return `<a class="list-card reveal" href="#messages/${id}">${avatar(a)}<div class="list-main"><h3>${a.name}</h3><p>${i?'I would love to see the floor plan.':'The terrace views look incredible.'}</p></div><div><time>${i?'10:45 AM':'11:21 AM'}</time><span class="unread">${i?1:3}</span></div></a>`}).join('')}</section></div><div class="stats-strip">${[[126,'Total residences','2 blocks',100],[100,'Available homes','79% of total',79],[7,'Residential floors','Full collection',100],[state.favorites.length,'Your saved homes','Made for you',Math.min(100,state.favorites.length*15)]].map(([n,l,t,p])=>`<div class="stat-card reveal"><strong>${count(n)}</strong><small>${l}</small><span class="stat-trend">${t}</span><div class="stat-progress"><i style="--progress:${p}%"></i></div></div>`).join('')}</div>${note()}`}
function getDeals(){if(!state.deals)state.deals=[{id:'deal-1',name:'Sophie Bennett',unitId:'A-21',stage:'Discovery',accountId:'account-5'},{id:'deal-2',name:'James Wilson',unitId:'B-27',stage:'Viewing',accountId:'account-6'},{id:'deal-3',name:'Olivia Reed',unitId:'A-48',stage:'Proposal',accountId:'account-3'},{id:'deal-4',name:'Daniel Brooks',unitId:'B-43',stage:'Discovery',accountId:'account-4'}];return state.deals}
