function collectionList(savedOnly=false){let list=D.units.filter(u=>(!savedOnly||state.favorites.includes(u.id))&&(!state.filters.query||`${u.id} ${u.title} ${u.block}`.toLowerCase().includes(state.filters.query.toLowerCase()))&&(state.filters.beds==='all'||u.beds===+state.filters.beds)&&(state.filters.block==='all'||u.block===state.filters.block)&&(state.filters.status==='all'||u.status===state.filters.status));if(state.filters.sort==='low')list.sort((a,b)=>a.price-b.price);if(state.filters.sort==='high')list.sort((a,b)=>b.price-a.price);if(state.filters.sort==='area')list.sort((a,b)=>b.area-a.area);if(state.filters.sort==='featured')list.sort((a,b)=>(a.status==='available'?-1:1)-(b.status==='available'?-1:1)||b.floor-a.floor);return list}
function renderCollection(savedOnly=false){const list=collectionList(savedOnly),pageSize=8,pages=Math.max(1,Math.ceil(list.length/pageSize));state.page=Math.min(state.page,pages);$('#main').innerHTML=`${pageTop(savedOnly?'Your private collection':'The Ghadir collection',savedOnly?'Places you love.':'Find your next chapter.',`${list.length} residences · 78.5–153.7 m²`,`${goButton('explore','Open visual unit explorer','floor','white')}`)}<div class="collection-toolbar"><label class="input-search">${icon('search')}<input id="unitSearch" aria-label="Search residences" placeholder="Search residence ID…" value="${esc(state.filters.query)}"></label><select class="pill" data-unit-filter="beds" aria-label="Filter bedrooms"><option value="all">All bedrooms</option><option value="2" ${state.filters.beds==='2'?'selected':''}>2 bedrooms</option><option value="3" ${state.filters.beds==='3'?'selected':''}>3 bedrooms</option></select><select class="pill" data-unit-filter="status" aria-label="Filter availability">${['all','available','reserved','sold'].map(v=>`<option value="${v}" ${state.filters.status===v?'selected':''}>${v==='all'?'All statuses':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><select class="pill" data-unit-filter="sort" aria-label="Sort residences">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['area','Largest first']].map(([v,l])=>`<option value="${v}" ${state.filters.sort===v?'selected':''}>${l}</option>`).join('')}</select>${button('collection-filter','settings','More filters','white')}</div><div class="unit-grid">${list.slice((state.page-1)*pageSize,state.page*pageSize).map(card).join('')||empty('heart',savedOnly?'Your collection starts here.':'No homes found.',savedOnly?'Save the spaces that feel like you. They will be waiting here.':'Try another residence ID or reset your filters.','residences','Explore residences')}</div>${list.length?`<div class="pagination"><span>Showing ${(state.page-1)*pageSize+1}–${Math.min(state.page*pageSize,list.length)} of ${list.length}</span><div class="button-group"><button class="pill" data-action="page-prev" ${state.page===1?'disabled':''}>${icon('left')}Previous</button><span>${state.page} / ${pages}</span><button class="pill" data-action="page-next" ${state.page===pages?'disabled':''}>Next${icon('right')}</button></div></div>`:''}<div id="compareDock">${compareDock()}</div>${note()}`}
function compareDock(){return state.compare.length?`<div class="compare-dock"><span>${state.compare.length} residences selected</span><button class="primary" data-action="compare">Compare homes${icon('arrow')}</button>${button('clear-compare','close','Clear comparison','sm')}</div>`:''}
