function floorSVG(selectedId){return `<svg class="plan-svg" viewBox="0 0 100 100" role="group" aria-label="Floor ${state.floor}, select a residence"><image href="assets/ghadir/floor-${state.floor}.jpg" width="100" height="100"/>${D.units.filter(u=>u.floor===state.floor).map(u=>`<polygon points="${u.points}" class="unit-zone ${u.id===selectedId?'selected':''}" data-action="select-plan-unit" data-id="${u.id}" data-status="${u.status}" role="button" tabindex="0" aria-label="Select residence ${u.id}, ${u.area} square meters, ${u.beds} bedrooms" aria-pressed="${u.id===selectedId}"><title>Residence ${u.id} · ${u.area} m² · ${u.beds} beds</title></polygon>`).join('')}</svg>`}
function renderExplorer(){const u=unit(state.selected);if(u.floor!==state.floor)state.selected=D.units.find(x=>x.floor===state.floor).id;$('#main').innerHTML=`${pageTop('Interactive residence finder','Your home. Your perspective.','Choose a floor, then select a residence.',`<button class="pill" data-action="scene-gallery">${icon('image')}Project gallery</button>`)}<div class="floor-pills"><span>FLOOR</span>${Array.from({length:7},(_,i)=>`<button class="${state.floor===i+1?'active':''}" data-action="floor" data-floor="${i+1}" aria-label="Floor ${i+1}" aria-pressed="${state.floor===i+1}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><section class="plan-panel reveal"><div class="plan-header"><h3>Floor ${state.floor} · Blocks A & B</h3>${button('floor-full','area','Enlarge floor plan','sm')}</div>${floorSVG(state.selected)}<div class="plan-legend"><span><i></i>Available</span><span><i></i>Reserved</span><span><i></i>Sold</span><span>Tap a home to select</span></div></section><div id="selectedUnit" style="margin-top:15px">${selectedUnit()}</div><div class="section-heading"><h2>${icon('grid')}On this floor</h2><span class="eyebrow">18 residences</span></div><div class="unit-chip-grid">${D.units.filter(u=>u.floor===state.floor).map(u=>`<button class="unit-chip ${u.id===state.selected?'active':''} ${u.status}" data-action="select-plan-unit" data-id="${u.id}">${u.id}<small>${u.area} m² · ${u.beds} beds</small></button>`).join('')}</div><p class="data-note">Original architectural drawings. Unit areas and bedrooms come from the project brochure; availability is illustrative. Original annotations are preserved in the drawings.</p>${note()}`}
function selectedUnit(){const u=unit(state.selected);return `<section class="selected-unit"><div>${badge(u.status)}<h2>Residence ${u.id}</h2><p>${u.area} m² · ${u.beds} bedrooms · Floor ${u.floor} · Block ${u.block}</p></div><div class="button-group">${button('favorite','heart','Save residence','',`data-id="${u.id}" aria-pressed="${state.favorites.includes(u.id)}"`)}<a class="primary" href="#unit/${u.id}">Discover this home${icon('arrow')}</a></div></section>`}
function unitCrop(u){const pairs=u.points.split(' ').map(p=>p.split(',').map(Number)),xs=pairs.map(p=>p[0]),ys=pairs.map(p=>p[1]),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y;return `<svg class="unit-plan-crop" viewBox="${x-1} ${y-1} ${w+2} ${h+2}" role="img" aria-label="Original plan of residence ${u.id}"><defs><clipPath id="unitClip"><polygon points="${u.points}"/></clipPath></defs><image href="${u.plan}" width="100" height="100" clip-path="url(#unitClip)"/></svg>`}
function renderUnit(id){const u=unit(id);state.selected=u.id;state.floor=u.floor;save('selected',u.id);const a=person(u.advisorId);$('#main').innerHTML=`${pageTop('The Ghadir collection','A space to make your own.','Residence '+u.id+' · Private property portfolio',`<a class="pill" href="#residences">${icon('left')}All homes</a>`)}<div class="detail-hero reveal"><img id="detailMainPhoto" src="${D.gallery[0].src}" alt="${D.gallery[0].alt}"><div class="detail-image-actions"><button class="pill" data-action="gallery" data-index="0">${icon('image')}View gallery</button><button class="pill" data-action="floor-full">${icon('floor')}Floor plan</button></div></div><div class="detail-thumbs">${D.gallery.map((g,i)=>`<button class="${i===0?'active':''}" data-action="detail-photo" data-index="${i}" aria-label="Show ${g.title}" aria-pressed="${i===0}"><img src="${g.src}" alt="${g.title}" loading="lazy"></button>`).join('')}</div><div class="detail-heading"><div><span class="eyebrow">GHADIR RESIDENCES / BLOCK ${u.block}</span><h1 style="margin-top:8px">Residence ${u.id}</h1><p>Pardisan, Qom · ${u.beds}-bedroom apartment</p></div><div class="price">${count(u.price,'$')}<small>ILLUSTRATIVE ASKING PRICE</small></div></div>${badge(u.status)}<div class="detail-facts">${[['area',u.area,'Living area · m²'],['bed',u.beds,'Bedrooms'],['floor',u.floor,'Residential floor'],['building',u.block,'Building block']].map(([i,v,l])=>`<div class="detail-fact reveal">${icon(i)}<strong>${typeof v==='number'?count(v,'','',v%1?1:0):v}</strong><small>${l}</small></div>`).join('')}</div><div class="detail-tabs" role="tablist">${[['overview','Overview'],['plan','Floor plan'],['payment','Payment plan'],['documents','Documents']].map(([v,l])=>`<button role="tab" aria-selected="${state.unitTab===v}" class="${state.unitTab===v?'active':''}" data-action="unit-tab" data-tab="${v}">${l}</button>`).join('')}</div><section id="unitTabBody" class="prose">${unitTabContent(u)}</section><div class="booking-strip">${personInline(a)}<div class="button-group">${button('favorite','heart','Save residence','',`data-id="${u.id}" aria-pressed="${state.favorites.includes(u.id)}"`)}<button class="primary" data-action="book" data-id="${u.id}">${u.status==='sold'?'Request alternatives':'Arrange a viewing'}${icon('arrow')}</button></div></div><p class="data-note">${esc(D.meta.imageryNotice)} Prices and availability are illustrative.</p>${note()}`;renderScene()}
function unitTabContent(u){if(state.unitTab==='plan')return `<h2>Every detail, thoughtfully placed.</h2><p>Explore the original plan of Residence ${u.id}, with ${u.area} m² of space on Floor ${u.floor}. This selection is extracted from the supplied architectural drawing.</p>${unitCrop(u)}<div class="button-group" style="margin-top:18px"><button class="primary" data-action="floor-full">View full floor${icon('area')}</button><a class="pill" href="#explore">Select another residence${icon('arrow')}</a></div>`;if(state.unitTab==='payment')return `<h2>A clear path to your next home.</h2><p>An illustrative purchase schedule, tailored to the residence you are exploring.</p><div class="timeline">${[['Reservation',.05,'Secure your place in the collection'],['Contract signing',.25,'Confirm the purchase agreement'],['Final handover',.70,'Your new chapter begins']].map(([t,n,d],i)=>`<div class="timeline-item"><span class="timeline-number">0${i+1}</span><div><h3>${t} · ${n*100}%</h3><p>${d}</p></div><strong>${money(u.price*n)}</strong></div>`).join('')}</div><div class="calculator"><h3>Explore a financing scenario</h3><div class="range-row"><label for="downRange">Down payment <output id="downLabel">30%</output></label><input id="downRange" type="range" min="10" max="80" value="30" step="5"></div><div class="range-row"><label for="yearsRange">Term <output id="yearsLabel">20 years</output></label><input id="yearsRange" type="range" min="5" max="30" value="20" step="5"></div><div class="range-row"><label for="rateRange">Annual interest <output id="rateLabel">5%</output></label><input id="rateRange" type="range" min="0" max="12" value="5" step="0.25"></div><div class="calculator-result"><small>Estimated monthly payment</small><strong id="monthlyPayment">${money(monthly(u.price,.30,20,5))}</strong></div><p class="data-note" style="margin-bottom:0">Scenario only. Taxes, insurance and fees are excluded. No financing offer is implied.</p></div>`;if(state.unitTab==='documents')return `<h2>Your residence, on record.</h2>${[['floor','Original floor plan','Floor '+u.floor+' · Architectural drawing'],['summary','Residence information sheet','Unit '+u.id+' · English summary'],['schedule','Illustrative payment schedule','Three milestones · USD']].map(([v,t,d])=>`<div class="asset-doc">${icon('file')}<div><h3>${t}</h3><p>${d}</p></div>${button(v==='floor'?'download-floor':v==='summary'?'download-unit':'download-schedule','download','Download '+t,'',`data-id="${u.id}"`)}</div>`).join('')}`;return `<h2>Room for the life you imagine.</h2><p>${esc(u.description)} Designed with a sense of openness and a considered connection to the shared spaces around you, this is a home to discover at your own pace.</p><div class="amenity-grid">${[...D.amenities.map(a=>[a.icon,a.name]),['shield','Shared amenities'],['building','Zagros development']].map(([i,l])=>`<div class="amenity">${icon(i)}${l}</div>`).join('')}</div><p class="data-note">Areas, bedrooms, floor and block follow the supplied Ghadir brochure. Interior images show the design of the wider project.</p>`}
function monthly(price,down,years,rate){const principal=price*(1-down),r=rate/1200,n=years*12;return r===0?principal/n:principal*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1)}
function renderAccounts(){const accounts=allAccounts();$('#main').innerHTML=`${pageTop('People & relationships','Good homes. Great people.','Your advisors, clients and workspace accounts.',`<button class="primary" data-action="add-account">${icon('plus')}Add account</button>`)}<div class="input-search" style="margin-bottom:20px">${icon('search')}<input id="accountSearch" placeholder="Search names, roles or email…" aria-label="Search accounts"></div><div class="account-grid" id="accountGrid">${accounts.map(accountCard).join('')}</div>${note()}`}
function accountCard(a){return `<article class="account-card reveal"><div class="person-inline">${avatar(a)}<div><small>${esc(a.role)}</small><p>${esc(a.name)}</p></div>${goButton('account/'+a.id,'Open '+a.name,'arrow','sm black')}</div><div class="account-info"><span>${icon('mail')}${esc(a.email)}</span><span>${icon('phone')}${esc(a.phone||'Not provided')}</span><span>${icon('briefcase')}${esc(a.company||'Private client')}</span></div><div class="account-card-footer"><span class="badge">${a.role==='Buyer'?'Private client':'Team member'}</span><div class="button-group">${button('contact','phone','Contact '+a.name,'sm',`data-id="${a.id}"`)}${button('message-person','mail','Message '+a.name,'sm',`data-id="${a.id}"`)}</div></div></article>`}
function renderAccount(id){const a=person(id);$('#main').innerHTML=`${pageTop('Account profile',a.role,'Every relationship, thoughtfully managed.',`<a class="pill" href="#accounts">${icon('left')}All accounts</a>`)}<div class="account-cover"></div><section class="account-profile"><div class="profile-top-row">${avatar(a,'large')}<div class="button-group">${button('edit-account','edit','Edit account','sm',`data-id="${a.id}"`)}<button class="primary" data-action="message-person" data-id="${a.id}">${icon('chat')}Conversation</button></div></div><h1>${esc(a.name)}</h1><p class="role-line">${esc(a.company||'Private client')} · ${esc(a.specialty||a.role)}</p><p class="profile-bio">${esc(a.bio||'A member of your Ghadir property workspace. Manage contact details, conversations and property interests in one place.')}</p><div class="profile-details">${[['Email address',a.email],['Phone number',a.phone||'Not provided'],['Location',a.office||a.location||'Private client studio'],['Languages',(a.languages||['English']).join(',')]].map(([l,v])=>`<div><label>${l}</label><span>${esc(v)}</span></div>`).join('')}</div></section><div class="stats-strip">${[[a.role==='Buyer'?3:18,'Property interests'],[a.role==='Buyer'?1:7,'Upcoming viewings'],[a.role==='Buyer'?2:24,'Conversations'],[a.role==='Buyer'?1:6,'Open opportunities']].map(([v,l])=>`<div class="stat-card reveal"><strong>${count(v)}</strong><small>${l}</small></div>`).join('')}</div>${section('Property interests','building','residences')}<div class="unit-grid">${D.units.filter(u=>u.status==='available').slice(a.role==='Buyer'?2:5,a.role==='Buyer'?4:7).map(card).join('')}</div><p class="data-note">This is a sample account profile. Edit contact information to personalize your workspace.</p>${note()}`}
function renderPipeline(){const deals=getDeals();$('#main').innerHTML=`${pageTop('From conversation to keys','Make the next move.','A clear view of every property opportunity.',`<button class="primary" data-action="add-deal">${icon('plus')}New opportunity</button>`)}<div class="stats-strip" style="margin:0 0 22px">${[[deals.length,'Open opportunities'],[num(deals.reduce((s,d)=>s+unit(d.unitId).price,0)/1e6,2)+'M','Illustrative pipeline'],[deals.filter(d=>d.stage==='Viewing').length,'Viewing stage'],[deals.filter(d=>d.stage==='Proposal').length,'Proposal stage']].map(([v,l])=>`<div class="stat-card"><strong>${typeof v==='number'?count(v):v}</strong><small>${l}</small></div>`).join('')}</div><div class="board">${['Discovery','Viewing','Proposal'].map(stage=>`<section class="board-column"><h3>${stage}<span>${deals.filter(d=>d.stage===stage).length}</span></h3>${deals.filter(d=>d.stage===stage).map(d=>`<article class="deal-card reveal"><span class="eyebrow">RESIDENCE ${d.unitId}</span><h3>${esc(d.name)}</h3><p>${unit(d.unitId).area} m² · ${unit(d.unitId).beds} bedrooms</p><strong class="deal-value">${count(unit(d.unitId).price,'$')}</strong><div class="deal-footer">${avatar(person(d.accountId))}<select class="pill" data-deal-stage="${d.id}" aria-label="Update stage for ${esc(d.name)}">${['Discovery','Viewing','Proposal'].map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select>${goButton('unit/'+d.unitId,'Open residence '+d.unitId,'arrow','sm black')}</div></article>`).join('')||'<p class="data-note">Ready for the next opportunity.</p>'}</section>`).join('')}</div>${note()}`}
const seedVisits=[{id:'visit-1',name:'Sophie Bennett',email:'sophie.bennett@example.com',unitId:'A-21',date:'2026-10-15',time:'10:30',type:'Private viewing'},{id:'visit-2',name:'James Wilson',email:'james.wilson@example.com',unitId:'B-27',date:'2026-10-16',time:'14:00',type:'Video consultation'},{id:'visit-3',name:'Olivia Reed',email:'olivia.reed@example.com',unitId:'A-48',date:'2026-10-18',time:'11:00',type:'Private viewing'}];
const allVisits=()=>[...seedVisits.filter(v=>!read('cancelledVisits',[]).includes(v.id)),...state.visits].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
function renderViewings(){const y=state.calendarYear,m=state.calendarMonth,first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),visits=allVisits();$('#main').innerHTML=`${pageTop('Your next visit','Step inside your future.','Plan a private viewing or a personal consultation.',`<button class="primary" data-action="book" data-id="${state.selected}">${icon('plus')}New viewing</button>`)}<section class="calendar"><div class="calendar-head"><h3>${new Date(y,m).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3><div class="button-group">${button('month-prev','left','Previous month','sm')}${button('month-next','right','Next month','sm')}</div></div><div class="calendar-days">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{let date=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<button class="calendar-day ${state.calendarDay===date?'selected':''} ${visits.some(v=>v.date===date)?'has-event':''} ${date==='2026-10-13'?'today':''}" data-action="calendar-day" data-date="${date}" aria-label="${date}">${i+1}</button>`}).join('')}</div></section>${section('Upcoming viewings','calendar')}<div id="viewingList">${visits.map(v=>`<article class="appointment reveal"><div class="appointment-time">${esc(v.time)}<small>${new Date(v.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></div><div><h3>${esc(v.name)} · Residence ${v.unitId}</h3><p>${esc(v.type)} · Ghadir Residences</p></div>${button('viewing-detail','arrow','Viewing details','black',`data-id="${v.id}"`)}</article>`).join('')||empty('calendar','A little room in your calendar.','Schedule a viewing to see your plans here.','','')}</div>${note()}`}
function renderDocuments(){const files=[...D.floors.map(f=>({title:'Floor '+f.floor+' · Architectural plan',description:'Original source drawing · JPG',img:f.src,action:'download-floor',floor:f.floor})),{title:'Your property collection',description:'All 126 residence specifications · CSV',action:'export-units',img:''},{title:'Residence '+state.selected,description:'English residence summary · TXT',action:'download-unit',img:''}];$('#main').innerHTML=`${pageTop('Your property library','Everything, in its place.','Original plans, residence information and exports.')}<div class="document-grid">${files.map((f,i)=>`<article class="document-card reveal" style="--delay:${i%3*60}ms"><div class="document-preview">${f.img?`<img src="${f.img}" alt="${f.title}" loading="lazy">`:icon('file')}</div><h3>${f.title}</h3><p>${f.description}</p><div class="button-group">${f.img?`<button class="pill" data-action="floor-full" data-floor="${f.floor}">Preview</button>`:'<span class="badge">English</span>'}${button(f.action,'download','Download '+f.title,'sm black',`data-floor="${f.floor||''}" data-id="${state.selected}"`)}</div></article>`).join('')}</div>${note()}`}
function renderPayments(){const u=unit(state.selected);$('#main').innerHTML=`${pageTop('Purchase planning','Clarity at every step.','Explore the financial picture for your selected residence.',`<button class="pill" data-action="download-schedule" data-id="${u.id}">${icon('download')}Export</button>`)}<section class="featured" style="padding:22px"><div class="featured-line"><div><span class="eyebrow">SELECTED RESIDENCE</span><h2 style="margin-top:8px">${u.id} · Block ${u.block} · Floor ${u.floor}</h2></div><div class="price">${count(u.price,'$')}<small>ILLUSTRATIVE VALUE</small></div></div><a class="pill" style="margin-top:20px" href="#residences">Choose another home${icon('arrow')}</a></section><div class="section-heading"><h2>${icon('wallet')}Payment milestones</h2><span class="badge">Illustrative schedule</span></div><div class="table-scroll"><table><thead><tr><th>Milestone</th><th>Share</th><th>Amount</th><th>Status</th></tr></thead><tbody>${[['Reservation',5],['Contract signing',25],['Final handover',70]].map(([n,v])=>`<tr><td>${n}</td><td>${v}%</td><td>${money(u.price*v/100)}</td><td><span class="badge reserved">Not initiated</span></td></tr>`).join('')}</tbody></table></div><div class="prose" style="margin-top:25px">${(()=>{let old=state.unitTab;state.unitTab='payment';let html=unitTabContent(u);state.unitTab=old;return html.slice(html.indexOf('<div class="calculator"'))})()}</div>${note()}`}
const initialMessages=id=>[{text:id==='account-6'?'Hello! Could you help me compare the two-bedroom layouts?':'Hi! I’m interested in a three-bedroom residence with an open view.',mine:false,time:'10:42 AM'},{text:'Of course. The Ghadir collection has a range of thoughtful layouts. Which floor feels right for you?',mine:true,time:'10:45 AM'},{text:id==='account-6'?'I would love to see the floor plan.':'The terrace views look incredible. Can we arrange a viewing?',mine:false,time:'11:21 AM'}];
function renderMessages(id){if(id)state.conversation=id;const a=person(state.conversation),contacts=[person('account-5'),person('account-6'),...advisors];if(!contacts.some(p=>p.id===a.id))contacts.push(a);const msgs=state.messages[a.id]||initialMessages(a.id);$('#main').innerHTML=`${pageTop('Stay connected','A conversation away.','Keep every property conversation in one place.')}<div class="conversation-layout"><aside class="conversation-list">${contacts.map(p=>`<a href="#messages/${p.id}" class="conversation-person ${a.id===p.id?'active':''}">${avatar(p)}<div><p>${esc(p.name)}</p><small>${esc(p.role)}</small></div></a>`).join('')}</aside><section class="conversation-main"><header class="conversation-header">${personInline(a)}${button('contact','phone','Contact details','sm',`data-id="${a.id}"`)}</header><div class="chat-messages" id="chatMessages">${msgs.map(m=>chatBubble(m)).join('')}</div><form class="chat-compose" id="chatForm"><input name="message" aria-label="Write a message" placeholder="Write a message…" required maxlength="3000"><button class="icon-button accent" type="submit" aria-label="Add message">${icon('right')}</button></form><p class="chat-note">Conversations are saved in this browser workspace.</p></section></div>${note()}`}
function chatBubble(m){return `<div class="chat-bubble ${m.mine?'mine':''}">${esc(m.text)}<small>${esc(m.time)}</small></div>`}
function renderInsights(){const available=D.units.filter(u=>u.status==='available').length;$('#main').innerHTML=`${pageTop('The wider perspective','A little more insight.','A considered view of the Ghadir collection.',`<button class="pill" data-action="export-units">${icon('download')}Export</button>`)}<div class="stats-strip" style="margin-top:0">${[[126,'Total residences'],[available,'Available · sample'],[78.5,'Minimum area · m²'],[153.7,'Maximum area · m²']].map(([v,l])=>`<div class="stat-card reveal"><strong>${count(v,'','',v%1?1:0)}</strong><small>${l}</small><div class="stat-progress"><i style="--progress:100%"></i></div></div>`).join('')}</div><section class="chart-card reveal"><div class="chart-header"><div><h3>The collection, floor by floor.</h3><p>Original residence count on each residential level</p></div><span class="badge">126 homes</span></div><div class="bar-chart">${D.floors.map((f,i)=>`<div class="bar" style="--height:85%;--delay:${i*75}ms"><small>18</small><span>Floor ${f.floor}</span></div>`).join('')}</div></section><div class="insights-bottom"><section class="chart-card reveal"><div class="chart-header"><h3>Availability</h3><span class="badge">Sample</span></div><div class="donut"><div><strong>${count(available)}</strong><small>Available homes</small></div></div><div class="plan-legend"><span><i></i>100 available</span><span><i></i>16 reserved</span><span><i></i>10 sold</span></div></section><section class="chart-card reveal"><h3>A room for every chapter.</h3><p class="data-note">Bedroom mix from the original brochure.</p>${[2,3].map(b=>{const n=D.units.filter(u=>u.beds===b).length;return `<div class="settings-row"><div><h4>${b}-bedroom residences</h4><p>${Math.round(n/126*100)}% of the collection</p></div><strong style="font-size:26px;font-weight:400">${count(n)}</strong></div>`}).join('')}<a class="pill" href="#residences" style="margin-top:15px">Discover the collection${icon('arrow')}</a></section></div>${note()}`}
function renderSettings(){const p=state.profile;$('#main').innerHTML=`${pageTop('Make yourself at home','Your workspace, your way.','Personal details, appearance and saved workspace data.')}<section class="settings-panel"><h3>Your account</h3><form class="settings-form" id="settingsForm"><label class="field">Full name<input name="name" value="${esc(p.name)}" required maxlength="80"></label><label class="field">Email address<input type="email" name="email" value="${esc(p.email)}" required></label><label class="field">Phone number<input name="phone" value="${esc(p.phone)}" type="tel"></label><label class="field">Role<input name="role" value="${esc(p.role)}" required></label><div class="form-actions"><button class="primary" type="submit">Save account${icon('check')}</button></div></form></section><section class="settings-panel"><h3>Appearance & experience</h3><div class="settings-row"><div><h4>Dark appearance</h4><p>A softer workspace for the evening.</p></div><button class="switch" role="switch" aria-checked="${state.theme==='dark'}" aria-label="Dark appearance" data-action="theme"></button></div><div class="settings-row"><div><h4>Motion & animated numbers</h4><p>Subtle reveals, fluid cards and counting statistics.</p></div><button class="switch" role="switch" aria-checked="${state.motion}" aria-label="Motion and animated numbers" data-action="motion"></button></div></section><section class="settings-panel"><h3>Workspace data</h3><div class="settings-row"><div><h4>Download a workspace backup</h4><p>Your saved homes, contacts, viewings and conversations.</p></div>${button('backup','download','Download workspace backup')}</div><div class="settings-row"><div><h4>Restore a workspace backup</h4><p>Continue from a previously downloaded NODE backup.</p></div><label class="icon-button" aria-label="Restore workspace backup">${icon('file')}<input id="restoreBackup" type="file" accept="application/json" hidden></label></div><p class="data-note">Your edits are saved in this browser. Sales figures, prices and account identities are sample records; original unit areas, bedrooms and floor plans come from the Ghadir project.</p></section>${note()}`}
function renderHelp(){ $('#main').innerHTML=`${pageTop('A little guidance','Everything starts here.','A simple guide to your property workspace.')}<div class="support-grid">${[['floor','Find your residence','Open the unit explorer. Choose a floor and select a highlighted home on its original plan.','explore'],['heart','Build your shortlist','Save homes with the heart icon. Compare up to three residences side by side.','favorites'],['calendar','Plan your viewing','Choose a date and time from any residence. Your viewing will appear in your calendar.','viewings'],['users','Stay connected','Explore account profiles, update contact details and keep your conversations together.','accounts']].map(([i,t,d,r])=>`<a class="support-item reveal" href="#${r}">${icon(i)}<h3>${t} ↗</h3><p>${d}</p></a>`).join('')}</div>${section('Good to know','help')}<details open><summary>What is real project information?</summary><p>The 126 residence IDs, floor positions, areas, bedroom counts and architectural plans follow the supplied Ghadir brochure. Images are original project design renders. Prices, availability, contacts and sales records are sample data for this workspace.</p></details><details><summary>Where is my information saved?</summary><p>Edits are saved in this browser. You can export and restore your workspace from Settings. This version does not send email, make payments or submit bookings to an external service.</p></details><details><summary>Can I browse from my phone or tablet?</summary><p>Yes. The bottom navigation keeps the main pages close on mobile. Open the menu in the top bar for the complete workspace. The original plans can be enlarged in the gallery.</p></details><details><summary>How do I reduce animation?</summary><p>Turn off Motion in Settings. Your device’s reduced-motion preference is respected automatically.</p></details>${note()}`}
const modal=$('#modal');let modalReturnFocus=null;
function openModal(title,body,cls=''){modalReturnFocus=document.activeElement;modal.className=cls;modal.innerHTML=`<div class="modal-heading"><h2 id="modalTitle">${esc(title)}</h2>${button('close-modal','close','Close dialog','sm')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('input:not([type=hidden]),button')?.focus(),20)}
function closeModal(){modal.close();document.body.style.overflow='';modalReturnFocus?.focus({preventScroll:true})}modal.addEventListener('close',()=>document.body.style.overflow='');modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function showGallery(index=0,items=D.gallery){state.dialogGallery=items;state.galleryIndex=(index+items.length)%items.length;const g=items[state.galleryIndex];modalReturnFocus=document.activeElement;modal.className='gallery-modal';modal.innerHTML=`<div class="modal-heading"><h2 id="modalTitle">${esc(g.title)}</h2>${button('close-modal','close','Close gallery','sm')}</div><div class="gallery-main"><img src="${g.src}" alt="${esc(g.alt||g.title)}">${items.length>1?button('gallery-prev','left','Previous image','gallery-prev')+button('gallery-next','right','Next image','gallery-next'):''}</div><div class="gallery-caption"><span>${items===D.gallery?'Ghadir · Original project design renders':'Ghadir · Original architectural drawing'}</span><span>${String(state.galleryIndex+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span></div><div class="gallery-thumbs">${items.map((a,i)=>`<button class="${state.galleryIndex===i?'active':''}" data-action="gallery-thumb" data-index="${i}" aria-label="View ${esc(a.title)}"><img src="${a.src}" alt="${esc(a.title)}"></button>`).join('')}</div>`;if(!modal.open)modal.showModal();document.body.style.overflow='hidden';}
function showSceneGallery(){openModal('Choose your perspective',`<p>Explore the project imagery, or choose an image for your property explorer.</p><div class="unit-grid">${D.gallery.filter(g=>['hero','exterior','night','terrace'].includes(g.id)).map(g=>`<button class="photo-button" style="height:160px" data-action="set-scene" data-photo="${g.id}" aria-label="Use ${g.title}"><img src="${g.src}" alt="${g.title}"><span class="photo-label">${g.title}</span></button>`).join('')}</div><button class="primary" data-action="gallery" data-index="0" style="margin-top:18px;width:100%">Open full gallery${icon('arrow')}</button>`)}
function showCompare(){if(state.compare.length<2){toast('Select at least two residences to compare.');return}const units=state.compare.map(unit);openModal('A closer comparison',`<div class="table-scroll"><table class="compare-table"><thead><tr><th>Your collection</th>${units.map(u=>`<td><img src="assets/ghadir/${u.beds===3?'living':'bedroom'}.webp" alt="Project interior"><h3>Residence ${u.id}</h3></td>`).join('')}</tr></thead><tbody>${[['Asking price',u=>money(u.price)],['Living area',u=>u.area+' m²'],['Bedrooms',u=>u.beds],['Floor',u=>u.floor],['Block',u=>u.block],['Availability',u=>badge(u.status)]].map(([l,f])=>`<tr><th>${l}</th>${units.map(u=>`<td>${f(u)}</td>`).join('')}</tr>`).join('')}<tr><th>Discover more</th>${units.map(u=>`<td><a class="primary" data-close="true" href="#unit/${u.id}">View home${icon('arrow')}</a></td>`).join('')}</tr></tbody></table></div><p class="data-note">Prices and availability are illustrative. Areas and bedrooms follow original project specifications.</p>`,'compare-modal')}
function showBooking(id){const u=unit(id);openModal(u.status==='sold'?'Request similar residences':'Make time for your next home',`<p>Residence ${u.id} · ${u.area} m² · ${u.beds} bedrooms<br>${u.status==='sold'?'This residence is marked sold in the sample collection. Ask about similar layouts.':'Choose a time to explore the Ghadir collection with an advisor.'}</p><form id="bookingForm" data-unit="${u.id}"><div class="modal-grid"><label class="field">Full name<input name="name" required autocomplete="name" placeholder="Your full name" maxlength="100"></label><label class="field">Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label class="field">Preferred date<input type="date" name="date" min="${localDate()}" value="${state.calendarDay>=localDate()?state.calendarDay:localDate()}" required></label><label class="field">Preferred time<select name="time">${['09:00','10:30','12:00','14:00','15:30','17:00'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field full">Experience<select name="type"><option>Private viewing</option><option>Video consultation</option><option>Project introduction</option></select></label><label class="field full">Anything you would like us to know?<textarea name="notes" placeholder="Your priorities, preferred layout or questions…" maxlength="1000"></textarea></label></div><button class="primary accent" type="submit">Save viewing request${icon('arrow')}</button><p class="data-note">Your request is saved to this browser workspace. No external booking is submitted.</p></form>`)}
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function showAccountForm(id){const a=id?person(id):{name:'',role:'Buyer',email:'',phone:'',company:'Private client',bio:''};openModal(id?'Edit account':'A new connection',`<form id="accountForm" data-id="${id||''}"><div class="modal-grid">${[['name','Full name','text'],['email','Email address','email'],['phone','Phone number','tel'],['company','Organization','text']].map(([n,l,t])=>`<label class="field">${l}<input type="${t}" name="${n}" value="${esc(a[n]||'')}" ${['name','email'].includes(n)?'required':''} maxlength="150"></label>`).join('')}<label class="field full">Role<select name="role">${['Buyer','Property advisor','Investment advisor','Workspace owner','Developer'].map(r=>`<option ${a.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="field full">About<textarea name="bio" maxlength="800">${esc(a.bio||'')}</textarea></label></div><button class="primary" type="submit">Save account${icon('check')}</button></form>`)}
function showContact(id){const a=person(id);openModal('Stay connected',`${personInline(a)}<div class="profile-details" style="margin-bottom:25px"><div><label>Email address</label><span>${esc(a.email)}</span></div><div><label>Phone number</label><span>${esc(a.phone||'Not provided')}</span></div><div><label>Organization</label><span>${esc(a.company||'Private client')}</span></div><div><label>Role</label><span>${esc(a.role)}</span></div></div><div class="button-group"><button class="primary" data-action="message-person" data-id="${id}">${icon('chat')}Open conversation</button><button class="pill" data-action="copy-contact" data-id="${id}">${icon('link')}Copy details</button></div><p class="data-note">${a.sample?'Sample contact for this property workspace.':'Workspace contact.'}</p>`)}
function showFilters(){openModal('Find your kind of home',`<form id="filterForm"><div class="modal-grid"><label class="field">Building block<select name="block">${['all','A','B'].map(v=>`<option value="${v}" ${state.filters.block===v?'selected':''}>${v==='all'?'Both blocks':'Block '+v}</option>`).join('')}</select></label><label class="field">Bedrooms<select name="beds">${['all','2','3'].map(v=>`<option value="${v}" ${state.filters.beds===v?'selected':''}>${v==='all'?'Any layout':v+' bedrooms'}</option>`).join('')}</select></label><label class="field">Availability<select name="status">${['all','available','reserved','sold'].map(v=>`<option value="${v}" ${state.filters.status===v?'selected':''}>${v==='all'?'All statuses':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label class="field">Sort by<select name="sort">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['area','Largest homes']].map(([v,l])=>`<option value="${v}" ${state.filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="button-group"><button class="pill" type="button" data-action="reset-filters">Reset</button><button class="primary" type="submit" style="flex:1">Show residences${icon('arrow')}</button></div></form>`)}
function showSearch(){openModal('Find your next possibility',`<label class="search-field">${icon('search')}<input id="globalSearchInput" placeholder="Unit ID, account name, page…" aria-label="Search everything"></label><div id="searchResults">${searchResults('')}</div>`);setTimeout(()=>$('#globalSearchInput')?.focus(),50)}
function searchResults(q){const query=q.toLowerCase().trim(),units=D.units.filter(u=>`${u.id} residence block ${u.block}`.toLowerCase().includes(query)).slice(0,query?5:3),people=allAccounts().filter(a=>(a.name+' '+a.email).toLowerCase().includes(query)).slice(0,3),pages=nav.filter(([r,i,l])=>l.toLowerCase().includes(query)).slice(0,query?3:0);return `${units.map(u=>`<a class="search-result" href="#unit/${u.id}" data-close="true"><img src="assets/ghadir/living.webp" alt="Project render"><div><h3>Residence ${u.id}</h3><p>${u.area} m² · ${u.beds} beds · ${money(u.price)}</p></div>${icon('arrow')}</a>`).join('')}${people.map(a=>`<a class="search-result" href="#account/${a.id}" data-close="true">${avatar(a)}<div><h3>${esc(a.name)}</h3><p>${esc(a.role)}</p></div>${icon('arrow')}</a>`).join('')}${pages.map(([r,i,l])=>`<a class="search-result" href="#${r}" data-close="true">${icon(i)}<h3>${l}</h3>${icon('arrow')}</a>`).join('')}${!units.length&&!people.length&&!pages.length?'<p class="data-note">No results. Try a residence ID such as A-21.</p>':''}`}
function showNotifications(){openModal('A little update',`<div class="notification">${icon('building')}<div><p>Your Ghadir collection is ready to explore.</p><small>126 residences · Original project plans</small></div></div><div class="notification">${icon('calendar')}<div><p>${state.visits.length?state.visits.length+' viewing request'+(state.visits.length>1?'s':'')+' saved in your workspace.':'Your next private viewing starts with a date.'}</p><small>Plan your next visit in Viewings</small></div></div><div class="notification">${icon('heart')}<div><p>${state.favorites.length} residence${state.favorites.length===1?'':'s'} in your private collection.</p><small>Bring your favorites together in Saved homes</small></div></div><a class="primary" style="margin-top:20px" href="#viewings" data-close="true">Open your calendar${icon('arrow')}</a>`)}
function showQuickAdd(){openModal('What’s your next move?',`${[['book','calendar','Arrange a viewing','Choose a residence, a day and a time.'],['add-account','users','Add a connection','Keep your people in one place.'],['add-deal','deal','New opportunity','Start the next property conversation.']].map(([a,i,t,s])=>`<button class="modal-option" data-action="${a}" data-id="${state.selected}">${icon(i)}<div><p>${t}</p><small>${s}</small></div><span class="arrow-icon">${icon('arrow')}</span></button>`).join('')}`)}
function showDealForm(){openModal('Start an opportunity',`<form id="dealForm"><label class="field">Client<select name="accountId">${allAccounts().map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label class="field">Residence<select name="unitId">${D.units.filter(u=>u.status!=='sold').map(u=>`<option value="${u.id}" ${u.id===state.selected?'selected':''}>${u.id} · ${u.area} m² · ${money(u.price)}</option>`).join('')}</select></label><label class="field">Stage<select name="stage"><option>Discovery</option><option>Viewing</option><option>Proposal</option></select></label><button class="primary" type="submit">Create opportunity${icon('arrow')}</button></form>`)}
function showViewingDetail(id){const v=allVisits().find(v=>v.id===id);if(!v)return;openModal('Your upcoming viewing',`<span class="badge">Saved request</span><h2 style="margin:17px 0">Residence ${v.unitId}</h2><div class="profile-details">${[['Guest',v.name],['Email',v.email],['Date',v.date],['Time',v.time],['Experience',v.type],['Notes',v.notes||'No additional notes']].map(([l,x])=>`<div><label>${l}</label><span>${esc(x)}</span></div>`).join('')}</div><div class="button-group" style="margin-top:25px"><a class="primary" href="#unit/${v.unitId}" data-close="true">Explore residence${icon('arrow')}</a><button class="pill" data-action="cancel-viewing" data-id="${id}">Cancel request</button></div><p class="data-note">This request is stored in your browser workspace.</p>`)}
function download(name,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadFloor(floor){const a=document.createElement('a');a.href=`assets/ghadir/floor-${floor}.jpg`;a.download=`Ghadir-Floor-${floor}-Original-Plan.jpg`;a.click();toast('Floor plan downloaded')}
function downloadUnit(id){const u=unit(id);download(`NODE-Residence-${u.id}.txt`,`NODE / GHADIR RESIDENCES\n\nResidence ${u.id}\nLocation: Pardisan, Qom\nDeveloper: Zagros Construction Group\nBlock: ${u.block}\nFloor: ${u.floor}\nLiving area: ${u.area} m²\nBedrooms: ${u.beds}\nIllustrative asking price: ${money(u.price)} USD\nIllustrative availability: ${u.status}\n\n${D.meta.imageryNotice}\n${D.meta.pricingNotice}\n\nOriginal unit facts follow the supplied Ghadir project brochure.\n`);toast('Residence summary downloaded')}
function exportUnits(){download('NODE-Ghadir-Residences.csv','Residence,Block,Floor,Area m2,Bedrooms,Sample price USD,Sample availability\n'+D.units.map(u=>[u.id,u.block,u.floor,u.area,u.beds,u.price,u.status].join(',')).join('\n'),'text/csv');toast('126 residences exported')}
function downloadSchedule(id){const u=unit(id);download(`NODE-${u.id}-Payment-Scenario.csv`,'Illustrative payment schedule - not an offer\nMilestone,Percent,Amount USD\n'+[['Reservation',5],['Contract signing',25],['Final handover',70]].map(([l,n])=>[l,n,u.price*n/100].join(',')).join('\n'),'text/csv');toast('Payment scenario downloaded')}
async function copyText(text,msg){try{await navigator.clipboard.writeText(text);toast(msg)}catch{openModal('Copy to clipboard',`<label class="field">Select and copy<textarea readonly>${esc(text)}</textarea></label>`)}}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function syncFavorites(){ $$('[data-action=favorite]').forEach(b=>{const on=state.favorites.includes(b.dataset.id);b.setAttribute('aria-pressed',on);b.style.color=on?'#859330':'';b.querySelector('svg')?.setAttribute('fill',on?'#dae4a5':'none')})}
let revealObserver,countObserver;
function animateContent(){const reduced=!state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;revealObserver?.disconnect();countObserver?.disconnect();revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach((e,i)=>{if(reduced)e.classList.add('visible');else{e.style.setProperty('--delay',`${Math.min(i%4,3)*60}ms`);revealObserver.observe(e)}});countObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){animateNumber(e.target,reduced);countObserver.unobserve(e.target)}}),{threshold:.4});$$('[data-count]').forEach(e=>countObserver.observe(e));syncFavorites()}
function animateNumber(el,reduced){const value=+el.dataset.count,prefix=el.dataset.prefix||'',suffix=el.dataset.suffix||'',dec=+el.dataset.decimals||0;if(reduced){el.textContent=prefix+num(value,dec)+suffix;return}const start=performance.now();function tick(now){if(!el.isConnected)return;const t=Math.min(1,(now-start)/1050),ease=1-Math.pow(1-t,4);el.textContent=prefix+num(dec?value*ease:Math.round(value*ease),dec)+suffix;if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}
function route(){if(modal.open)closeModal();const parts=decodeURIComponent(location.hash.slice(1)||'overview').split('/');currentPage=parts[0];document.body.classList.toggle('inner-route',currentPage!=='overview');renderNav();renderScene();const renders={overview:renderOverview,explore:renderExplorer,residences:()=>renderCollection(false),favorites:()=>renderCollection(true),unit:()=>{state.unitTab='overview';renderUnit(parts[1])},accounts:renderAccounts,account:()=>renderAccount(parts[1]),pipeline:renderPipeline,viewings:renderViewings,documents:renderDocuments,payments:renderPayments,messages:()=>renderMessages(parts[1]),insights:renderInsights,settings:renderSettings,help:renderHelp};(renders[currentPage]||renderOverview)();$('#main').classList.remove('page-enter');void $('#main').offsetWidth;$('#main').classList.add('page-enter');animateContent();document.title=`${currentPage==='unit'?'Residence '+state.selected:nav.find(n=>n[0]===currentPage)?.[2]||'Your workspace'} — NODE Residences`;window.scrollTo({top:0,behavior:'instant'});if(currentPage==='messages')scrollChat()}
function rerender(){const y=scrollY;route();window.scrollTo({top:y,behavior:'instant'})}function scrollChat(){setTimeout(()=>{const c=$('#chatMessages');if(c)c.scrollTop=c.scrollHeight},30)}
function selectPlan(id){const u=unit(id);state.selected=id;state.floor=u.floor;save('selected',id);$$('.unit-zone').forEach(x=>{x.classList.toggle('selected',x.dataset.id===id);x.setAttribute('aria-pressed',String(x.dataset.id===id))});$$('.unit-chip').forEach(x=>x.classList.toggle('active',x.dataset.id===id));if($('#selectedUnit'))$('#selectedUnit').innerHTML=selectedUnit();renderScene();syncFavorites()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(e.target.closest('[data-close]'))closeModal();if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
case 'close-modal':closeModal();break;
case 'search':showSearch();break;
case 'quick-add':showQuickAdd();break;
case 'notifications':showNotifications();break;
case 'profile':location.hash='account/account-1';break;
case 'menu':openModal('Your workspace',`<div class="modal-grid">${nav.map(([r,i,l])=>`<a class="modal-option" href="#${r}" data-close="true">${icon(i)}<p>${l}</p></a>`).join('')}</div>`);break;
case 'theme':state.theme=state.theme==='light'?'dark':'light';save('theme',state.theme);renderNav();if(currentPage==='settings')renderSettings();break;
case 'motion':state.motion=!state.motion;save('motion',state.motion);renderNav();renderSettings();break;
case 'explore':if(modal.open)closeModal();if(location.hash==='#explore'){renderExplorer();animateContent()}else location.hash='explore';break;
case 'scene-unit':state.selected=id;state.floor=unit(id).floor;save('selected',id);renderScene();if(currentPage==='overview'){renderOverview();animateContent()}else if(currentPage==='explore'){renderExplorer();animateContent()}else location.hash='unit/'+id;break;
case 'scene-gallery':showSceneGallery();break;
case 'set-scene':state.photo=b.dataset.photo;renderScene();closeModal();toast('Your perspective, updated.');break;
case 'scene-options':openModal('Your property view',`<p>Choose how you explore the Ghadir collection.</p><button class="modal-option" data-action="explore">${icon('floor')}<div><p>Interactive floor plans</p><small>126 residences across seven levels</small></div>${icon('arrow')}</button><button class="modal-option" data-action="scene-gallery">${icon('image')}<div><p>Change project image</p><small>Daylight, evening and terrace views</small></div>${icon('arrow')}</button><button class="modal-option" data-action="zoom-reset">${icon('target')}<div><p>Reset perspective</p><small>Return to the original framing</small></div></button>`);break;
case 'zoom-in':state.zoom=Math.min(1.8,state.zoom+.15);$('.scene-bg')?.style.setProperty('--scene-scale',state.zoom);break;
case 'zoom-out':state.zoom=Math.max(1,state.zoom-.15);$('.scene-bg')?.style.setProperty('--scene-scale',state.zoom);break;
case 'zoom-reset':state.zoom=1.02;renderScene();closeModal();break;
case 'gallery':showGallery(+b.dataset.index||0);break;
case 'gallery-prev':showGallery(state.galleryIndex-1,state.dialogGallery);break;
case 'gallery-next':showGallery(state.galleryIndex+1,state.dialogGallery);break;
case 'gallery-thumb':showGallery(+b.dataset.index,state.dialogGallery);break;
case 'detail-photo':{const g=D.gallery[+b.dataset.index];$('#detailMainPhoto').src=g.src;$('#detailMainPhoto').alt=g.alt;$('#detailMainPhoto').animate([{opacity:.4},{opacity:1}],{duration:400});$$('.detail-thumbs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('.detail-image-actions [data-action=gallery]').dataset.index=b.dataset.index;break}
case 'favorite':{const on=state.favorites.includes(id);state.favorites=on?state.favorites.filter(x=>x!==id):[...state.favorites,id];save('favorites',state.favorites);syncFavorites();toast(on?'Residence removed from your collection.':'A new favorite. Saved to your collection.');if(currentPage==='favorites'){renderCollection(true);animateContent()}break}
case 'share':copyText(location.origin+location.pathname+'#unit/'+id,'Residence link copied.');break;
case 'book':showBooking(id||state.selected);break;
case 'contact':showContact(id);break;
case 'message-person':closeModal();location.hash='messages/'+id;break;
case 'copy-contact':{const p=person(id);copyText(`${p.name}\n${p.email}\n${p.phone||''}`,'Contact details copied.');break}
case 'advisor-status':openModal('A personal point of contact',`<p>${esc(person(id).name)} · ${esc(person(id).role)}</p><button class="modal-option" data-action="book" data-id="${state.selected}">${icon('calendar')}<div><p>Arrange a private viewing</p><small>Choose a time for a closer look</small></div>${icon('arrow')}</button><button class="modal-option" data-action="message-person" data-id="${id}">${icon('chat')}<div><p>Start a conversation</p><small>Share your preferences and questions</small></div>${icon('arrow')}</button><a class="modal-option" href="#account/${id}" data-close="true">${icon('user')}<div><p>View profile</p><small>Contact details and property interests</small></div>${icon('arrow')}</a>`);break;
case 'collection-filter':showFilters();break;
case 'reset-filters':state.filters={query:'',beds:'all',block:'all',status:'all',sort:'featured'};state.page=1;closeModal();if(currentPage==='residences'||currentPage==='favorites'){renderCollection(currentPage==='favorites');animateContent()}else location.hash='residences';break;
case 'page-prev':state.page=Math.max(1,state.page-1);renderCollection(currentPage==='favorites');animateContent();$('#main').scrollIntoView({behavior:'smooth'});break;
case 'page-next':state.page++;renderCollection(currentPage==='favorites');animateContent();$('#main').scrollIntoView({behavior:'smooth'});break;
case 'compare':showCompare();break;
case 'clear-compare':state.compare=[];save('compare',[]);$$('[data-compare]').forEach(x=>x.checked=false);if($('#compareDock'))$('#compareDock').innerHTML='';break;
case 'floor':state.floor=+b.dataset.floor;state.selected=D.units.find(u=>u.floor===state.floor).id;renderExplorer();renderScene();animateContent();break;
case 'select-plan-unit':selectPlan(id);break;
case 'floor-full':{let floor=+b.dataset.floor||state.floor;showGallery(0,[{title:`Floor ${floor} · Original plan`,src:`assets/ghadir/floor-${floor}.jpg`}]);break}
case 'unit-tab':state.unitTab=b.dataset.tab;$$('[data-action=unit-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});$('#unitTabBody').innerHTML=unitTabContent(unit(state.selected));$('#unitTabBody').animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:300});break;
case 'add-account':showAccountForm();break;
case 'edit-account':showAccountForm(id);break;
case 'add-deal':showDealForm();break;
case 'month-prev':state.calendarMonth--;if(state.calendarMonth<0){state.calendarMonth=11;state.calendarYear--}renderViewings();animateContent();break;
case 'month-next':state.calendarMonth++;if(state.calendarMonth>11){state.calendarMonth=0;state.calendarYear++}renderViewings();animateContent();break;
case 'calendar-day':{state.calendarDay=b.dataset.date;$$('.calendar-day').forEach(x=>x.classList.toggle('selected',x===b));const found=allVisits().filter(v=>v.date===state.calendarDay);if(found.length)showViewingDetail(found[0].id);else showBooking(state.selected);break}
case 'viewing-detail':showViewingDetail(id);break;
case 'cancel-viewing':openModal('Cancel this viewing?',`<p>This removes the saved request from your workspace calendar.</p><div class="button-group"><button class="pill" data-action="close-modal">Keep viewing</button><button class="primary" data-action="confirm-cancel-viewing" data-id="${id}">Cancel request</button></div>`);break;
case 'confirm-cancel-viewing':state.visits=state.visits.filter(v=>v.id!==id);save('visits',state.visits);save('cancelledVisits',[...read('cancelledVisits',[]),id]);closeModal();renderViewings();animateContent();toast('Viewing request cancelled.');break;
case 'download-unit':downloadUnit(id||state.selected);break;
case 'download-floor':downloadFloor(+b.dataset.floor||unit(id||state.selected).floor);break;
case 'download-schedule':downloadSchedule(id||state.selected);break;
case 'export-units':exportUnits();break;
case 'backup':{const keys=['favorites','compare','accounts','accountEdits','deals','visits','cancelledVisits','messages','profile','theme','motion','selected'],data=Object.fromEntries(keys.map(k=>[k,read(k,k==='deals'?getDeals():null)]));download('NODE-workspace-backup.json',JSON.stringify({app:'NODE',version:1,exportedAt:new Date().toISOString(),data},null,2),'application/json');toast('Workspace backup downloaded.');break}
case 'data-info':openModal('About this collection',`<p>The original Ghadir project brochure is the source for 126 residence IDs, areas, bedroom counts and seven architectural floor plans.</p><div class="notification">${icon('check')}<div><p>Original project information</p><small>Unit dimensions, bedrooms, floors, blocks and project design renders.</small></div></div><div class="notification">${icon('eye')}<div><p>Illustrative workspace records</p><small>Prices, availability, account identities, pipeline opportunities and sales statistics.</small></div></div><p class="data-note">Your changes stay in this browser. Images illustrate the project’s design and are not assigned to individual residences. Original plan annotations remain in their source language.</p><a class="primary" href="#help" data-close="true">Explore the guide${icon('arrow')}</a>`);break;
}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.unitFilter){state.filters[el.dataset.unitFilter]=el.value;state.page=1;renderCollection(currentPage==='favorites');animateContent()}if(el.dataset.compare){const id=el.dataset.compare;if(el.checked&&state.compare.length>=3){el.checked=false;toast('Compare up to three residences at a time.');return}state.compare=el.checked?[...state.compare.filter(x=>x!==id),id]:state.compare.filter(x=>x!==id);save('compare',state.compare);if($('#compareDock'))$('#compareDock').innerHTML=compareDock()}if(el.dataset.dealStage){const d=getDeals().find(d=>d.id===el.dataset.dealStage);d.stage=el.value;save('deals',state.deals);renderPipeline();animateContent();toast('Opportunity moved to '+d.stage+'.')}if(el.id==='restoreBackup'&&el.files[0]){try{const raw=JSON.parse(await el.files[0].text());if(raw.app!=='NODE'||raw.version!==1||!raw.data)throw Error('Invalid');window.pendingBackup=raw.data;openModal('Restore your workspace?',`<p>This replaces saved contacts, favorites, viewings and conversations in this browser with the selected backup.</p><div class="button-group"><button class="pill" data-action="close-modal">Keep current</button><button class="primary" id="confirmRestore">Restore backup</button></div>`);$('#confirmRestore').onclick=()=>{for(const k of ['favorites','compare','accounts','accountEdits','deals','visits','cancelledVisits','messages','profile','theme','motion','selected'])if(raw.data[k]!==null&&raw.data[k]!==undefined)save(k,raw.data[k]);location.reload()}}catch{toast('Choose a valid NODE workspace backup.')}}});
let queryTimer;document.addEventListener('input',e=>{if(e.target.id==='globalSearchInput')$('#searchResults').innerHTML=searchResults(e.target.value);if(e.target.id==='unitSearch'){state.filters.query=e.target.value;clearTimeout(queryTimer);queryTimer=setTimeout(()=>{const pos=e.target.selectionStart;state.page=1;renderCollection(currentPage==='favorites');animateContent();const input=$('#unitSearch');input?.focus();input?.setSelectionRange(pos,pos)},240)}if(e.target.id==='accountSearch'){const q=e.target.value.toLowerCase();$('#accountGrid').innerHTML=allAccounts().filter(a=>(a.name+' '+a.role+' '+a.email).toLowerCase().includes(q)).map(accountCard).join('')||empty('users','No matching accounts.','Try a different name or email.','','');animateContent()}if(['downRange','yearsRange','rateRange'].includes(e.target.id)){const down=+$('#downRange').value,years=+$('#yearsRange').value,rate=+$('#rateRange').value;$('#downLabel').textContent=down+'%';$('#yearsLabel').textContent=years+' years';$('#rateLabel').textContent=rate+'%';$('#monthlyPayment').textContent=money(monthly(unit(state.selected).price,down/100,years,rate))}});
document.addEventListener('submit',e=>{const form=e.target;if(!['bookingForm','accountForm','filterForm','dealForm','settingsForm','chatForm'].includes(form.id))return;e.preventDefault();const f=Object.fromEntries(new FormData(form));switch(form.id){case 'bookingForm':state.visits.push({...f,id:'view-'+Date.now(),unitId:form.dataset.unit});save('visits',state.visits);state.calendarDay=f.date;state.calendarYear=+f.date.slice(0,4);state.calendarMonth=+f.date.slice(5,7)-1;closeModal();if(location.hash==='#viewings'){renderViewings();animateContent()}else location.hash='viewings';toast('Your viewing request is saved. A new chapter awaits.');break;
case 'accountForm':{const id=form.dataset.id;if(id){state.accountEdits[id]={...f};save('accountEdits',state.accountEdits);if(id==='account-1'){state.profile={...state.profile,...f};save('profile',state.profile)}}else{state.accounts.push({...f,id:'contact-'+Date.now(),initials:f.name.split(' ').map(x=>x[0]).join('').slice(0,2),color:'#dce6cf'});save('accounts',state.accounts)}closeModal();if(currentPage==='accounts')renderAccounts();else if(currentPage==='account')renderAccount(id);else location.hash='accounts';renderNav();animateContent();toast(id?'Account updated.':'A new connection, saved.');break}
case 'filterForm':state.filters={...state.filters,...f};state.page=1;closeModal();if(currentPage==='residences'||currentPage==='favorites'){renderCollection(currentPage==='favorites');animateContent()}else location.hash='residences';break;
case 'dealForm':getDeals().push({...f,id:'deal-'+Date.now(),name:person(f.accountId).name});save('deals',state.deals);closeModal();if(currentPage==='pipeline'){renderPipeline();animateContent()}else location.hash='pipeline';toast('A new opportunity is ready.');break;
case 'settingsForm':state.profile={...state.profile,...f};save('profile',state.profile);renderNav();toast('Your account is up to date.');break;
case 'chatForm':{const text=f.message.trim();if(!text)return;const id=state.conversation,m={text,mine:true,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tehran'})};state.messages[id]=[...(state.messages[id]||initialMessages(id)),m];save('messages',state.messages);$('#chatMessages').insertAdjacentHTML('beforeend',chatBubble(m));form.reset();scrollChat();break}
}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(modal.open&&modal.classList.contains('gallery-modal')){if(e.key==='ArrowRight'){e.preventDefault();showGallery(state.galleryIndex+1,state.dialogGallery)}if(e.key==='ArrowLeft'){e.preventDefault();showGallery(state.galleryIndex-1,state.dialogGallery)}}if(e.target.matches('.unit-zone')&&['Enter',' '].includes(e.key)){e.preventDefault();selectPlan(e.target.dataset.id)}});
window.addEventListener('hashchange',route);document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));route();
